1	//! Router wiring + server entry. Saga 21 step 001.
2	
3	use std::net::SocketAddr;
4	
5	use axum::Router;
6	use axum::routing::{get, post};
7	use mlpl_array::DenseArray;
8	use mlpl_eval::{EvalError, PeerDispatcher, Value};
