16	/// Errors the server can fail with at startup or
17	/// while serving. Translated to stderr + non-zero
18	/// exit by `main`.
19	#[derive(Debug)]
20	pub enum ServerError {
21	    /// `--bind 0.0.0.0` (or any non-loopback) without
22	    /// `--auth required`.
23	    InsecureBind { addr: SocketAddr },
24	    /// Failed to bind the listener socket.
25	    Bind(std::io::Error),
26	    /// Axum `serve` returned an error.
27	    Serve(std::io::Error),
28	}
29	
30	impl std::fmt::Display for ServerError {
31	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
32	        match self {
33	            Self::InsecureBind { addr } => write!(
34	                f,
35	                "refusing to bind {addr} with --auth disabled: \
36	                 non-loopback addresses require --auth required"
37	            ),
38	            Self::Bind(e) => write!(f, "bind failed: {e}"),
39	            Self::Serve(e) => write!(f, "serve failed: {e}"),
40	        }
41	    }
42	}
43	
44	impl std::error::Error for ServerError {}
45	
46	/// Shared state on the application: the session map,
47	/// the peer registry (Saga R1 step 003), and the
48	/// configured auth mode.
49	#[derive(Clone)]
50	pub struct AppState {
51	    pub sessions: SessionMap,
52	    pub peers: PeerRegistry,
53	    pub peer_sessions: PeerSessionMap,
54	    pub auth_mode: AuthMode,
55	}
56	
57	#[derive(Debug)]
58	pub struct RemoteMlxDispatcher {
59	    peers: PeerRegistry,
60	    sessions: PeerSessionMap,
61	}
62	
63	#[derive(Serialize)]
64	pub struct EvalOnDeviceBinding {
65	    pub name: String,
66	    pub tensor: String,
67	}
68	
69	#[derive(Serialize)]
70	struct EvalOnDeviceRequest {
71	    program: String,
72	    bindings: Vec<EvalOnDeviceBinding>,
73	}
74	
75	#[derive(Deserialize)]
76	struct EvalOnDeviceResponse {
77	    result: EvalResultPayload,
78	}
79	
80	#[derive(Deserialize)]
81	#[serde(tag = "kind", rename_all = "lowercase")]
82	enum EvalResultPayload {
83	    Tensor {
84	        handle: String,
85	        shape: Vec<usize>,
86	        device: String,
87	    },
88	    String {
89	        value: String,
90	    },
91	}
92	
93	#[derive(Deserialize)]
94	struct TransferResponse {
95	    tensor: String,
96	}
97	
98	impl RemoteMlxDispatcher {
99	    #[must_use]
100	    pub fn new(peers: PeerRegistry, sessions: PeerSessionMap) -> Self {
101	        Self { peers, sessions }
102	    }
103	}
104	
105	impl PeerDispatcher for RemoteMlxDispatcher {
106	    #[rustfmt::skip]
107	    fn dispatch_block(
108	        &self,
109	        device: &str,
110	        source: &str,
111	        bindings: std::collections::HashMap<String, DenseArray>,
112	    ) -> Option<Result<Value, EvalError>> {
113	        let peer = self.peers.get(device)?.clone();
114	        let session = self.sessions.get_or_create(&peer);
115	        let bindings = crate::peers::encode_bindings(bindings);
116	        let (session, bindings) = match (session, bindings) {
117	            (Ok(session), Ok(bindings)) => (session, bindings),
118	            (Err(e), _) | (_, Err(e)) => return Some(Err(e)),
119	        };
120	        let body = EvalOnDeviceRequest { program: source.to_string(), bindings };
121	        let url = format!(
122	            "{}/v1/sessions/{}/eval-on-device",
123	            peer.url.trim_end_matches('/'),
124	            session.id
125	        );
126	        let client = peer.client;
127	        let token = session.token;
128	        let result = std::thread::spawn(move || {
129	            client
130	                .post(url)
131	                .bearer_auth(&token)
132	                .json(&body)
133	                .send()
134	                .and_then(reqwest::blocking::Response::error_for_status)?
135	                .json::<EvalOnDeviceResponse>()
136	        })
137	        .join()
138	        .map_err(|_| EvalError::Unsupported("remote peer thread panicked".into()));
139	        Some(result.and_then(|r| {
140	            r.map_err(|e| EvalError::Unsupported(format!("remote peer request: {e}")))
141	        }).map(|r| match r.result {
142	            EvalResultPayload::Tensor { handle, shape, device } => {
143	                Value::DeviceTensor { peer: peer.url, handle, shape, device }
144	            }
145	            EvalResultPayload::String { value } => Value::Str(value),
146	        }))
147	    }
148	
149	    fn fetch_tensor(&self, peer_url: &str, handle: &str) -> Result<DenseArray, EvalError> {
150	        let peer = self
151	            .peers
152	            .values()
153	            .find(|p| p.url == peer_url)
154	            .ok_or_else(|| EvalError::Unsupported(format!("unknown peer {peer_url}")))?;
155	        let session = self.sessions.get_or_create(peer)?;
156	        let url = format!(
157	            "{}/v1/sessions/{}/transfer",
158	            peer.url.trim_end_matches('/'),
159	            session.id
160	        );
161	        let client = peer.client;
162	        let token = session.token;
163	        let handle = handle.to_string();
164	        let resp = std::thread::spawn(move || {
165	            client
166	                .post(url)
167	                .bearer_auth(&token)
168	                .json(&serde_json::json!({ "handle": handle }))
169	                .send()
170	                .and_then(reqwest::blocking::Response::error_for_status)?
171	                .json::<TransferResponse>()
172	        })
173	        .join()
174	        .map_err(|_| EvalError::Unsupported("remote peer thread panicked".into()))?
175	        .map_err(|e| EvalError::Unsupported(format!("remote peer request: {e}")))?;
176	        crate::peers::decode_from_json(&resp.tensor)
177	    }
178	}
