180	/// Build the axum router with the session-map state
181	/// and auth mode wired in. Empty peer registry; use
182	/// `build_app_with_peers` for tests that need to
183	/// register peers up-front.
184	pub fn build_app(auth_mode: AuthMode) -> Router {
185	    build_app_with_peers(auth_mode, crate::peers::empty_registry(), None)
186	}
187	
188	/// Saga R1 step 003 + Saga 25 step A: build the
189	/// router with an explicit peer registry and an
190	/// optional static-asset directory. Used by `run` and
191	/// by integration tests; `static_dir = None` keeps
192	/// the legacy API-only behavior.
193	pub fn build_app_with_peers(
194	    auth_mode: AuthMode,
195	    peers: crate::peers::PeerRegistry,
196	    static_dir: Option<&std::path::Path>,
197	) -> Router {
198	    let state = AppState {
199	        sessions: new_map(),
200	        peers,
201	        peer_sessions: PeerSessionMap::default(),
202	        auth_mode,
203	    };
204	    let mut router = Router::new()
205	        .route("/v1/health", get(health_handler))
206	        .route("/v1/sessions", post(create_session_handler))
207	        .route("/v1/sessions/:id/eval", post(eval_handler))
208	        .route(
209	            "/v1/sessions/:id/eval_stream",
210	            post(crate::sse::eval_stream_handler),
211	        )
212	        .route("/v1/sessions/:id/inspect", get(inspect_handler))
213	        .with_state(state);
214	    if let Some(dir) = static_dir {
215	        // The web build sets `--public-url /sw-mlpl/`, so
216	        // every asset reference in `pages/index.html` is
217	        // already prefixed with `/sw-mlpl/`. Mount the
218	        // ServeDir on that exact prefix so the same
219	        // committed `pages/` directory works locally and
220	        // on GitHub Pages without rebuilding.
221	        let serve = tower_http::services::ServeDir::new(dir);
222	        router = router.nest_service("/sw-mlpl", serve);
223	    }
224	    router
225	}
226	
227	/// Bind the listener at `addr`, refuse insecure
228	/// non-loopback binds, then `axum::serve` the
229	/// router. Used by `main`; tests call `build_app`
230	/// directly + run on their own listener.
231	///
232	/// Saga R1 step 003: `peers` carries the
233	/// `--peer mlx=<url>`-derived registry built up by
234	/// `peers::build_registry` in `main`. An empty
235	/// registry means "no peer routing; device-scoped
236	/// blocks fall back to in-process dispatch."
237	/// Optional TLS configuration. `None` keeps the legacy
238	/// HTTP path; `Some(config)` switches to
239	/// `axum_server::bind_rustls` so the same listener
240	/// terminates TLS for the /v1 API and the static UI.
241	pub type TlsConfig = Option<axum_server::tls_rustls::RustlsConfig>;
242	
243	pub async fn run(
244	    addr: SocketAddr,
245	    auth_mode: AuthMode,
246	    peers: crate::peers::PeerRegistry,
247	    static_dir: Option<std::path::PathBuf>,
248	    tls: TlsConfig,
249	) -> Result<(), ServerError> {
250	    if !addr.ip().is_loopback() && auth_mode == AuthMode::Disabled {
251	        return Err(ServerError::InsecureBind { addr });
252	    }
253	    let app = build_app_with_peers(auth_mode, peers, static_dir.as_deref());
254	    match tls {
255	        Some(config) => axum_server::bind_rustls(addr, config)
256	            .serve(app.into_make_service())
257	            .await
258	            .map_err(ServerError::Bind),
259	        None => {
260	            let listener = tokio::net::TcpListener::bind(addr)
261	                .await
262	                .map_err(ServerError::Bind)?;
263	            axum::serve(listener, app).await.map_err(ServerError::Serve)
264	        }
265	    }
266	}
