        if !check_token(provided, &entry.token) {
            return Err((
                StatusCode::UNAUTHORIZED,
                json_err("missing or invalid authorization"),
            ));
        }
    }
    entry.interrupt.set();
    Ok(Json(CancelResponse { cancelled: true }))
