        let mut on_metric = |m: &crate::connect_stream::SseMetric| {
            any_metric = true;
            let _ = render_metric(&mut stdout, m);
        };
        let r = eval_remote_stream(client, base_url, session_id, token, program, &mut on_metric);
        if any_metric {
