50	async fn read_sse_frames(resp: reqwest::Response) -> Vec<SseFrame> {
51	    use tokio_stream::StreamExt;
52	    let mut stream = resp.bytes_stream();
53	    let mut buf: Vec<u8> = Vec::new();
54	    while let Some(chunk) = stream.next().await {
55	        let bytes = chunk.unwrap();
56	        buf.extend_from_slice(&bytes);
57	    }
58	    let text = String::from_utf8(buf).unwrap();
59	    let mut frames = Vec::new();
60	    for block in text.split("\n\n") {
61	        if block.trim().is_empty() {
62	            continue;
63	        }
64	        let mut event_name: Option<String> = None;
65	        let mut data_lines: Vec<String> = Vec::new();
66	        for line in block.lines() {
67	            if let Some(rest) = line.strip_prefix("event:") {
68	                event_name = Some(rest.trim().to_string());
69	            } else if let Some(rest) = line.strip_prefix("data:") {
70	                data_lines.push(rest.trim().to_string());
71	            }
72	        }
73	        let event = match event_name {
74	            Some(e) => e,
75	            None => continue,
76	        };
77	        let data_str = data_lines.join("\n");
78	        let data = if data_str.is_empty() {
79	            JsonValue::Null
80	        } else {
81	            serde_json::from_str(&data_str).unwrap_or(JsonValue::Null)
82	        };
83	        frames.push(SseFrame { event, data });
84	    }
85	    frames
86	}
