1	//! Saga 21.5 step 003: cooperative cancellation in `eval_program`.
2	//!
3	//! The evaluator threads an `Interrupt` token through `Environment`.
4	//! When the token is tripped, every loop head (`for`, `train`,
5	//! `repeat`) and every pre-builtin checkpoint raises
6	//! `EvalError::Cancelled`. `train` enriches the bubbled error with
7	//! the current iteration index plus the partial loss curve so
8	//! clients can render what completed before the cancel landed;
9	//! `for` / `repeat` / pre-builtin sites raise an unenriched
10	//! `Cancelled` (empty `partial_losses`).
11	//!
12	//! Non-cancelled programs are unaffected: the `Interrupt` defaults
13	//! to `false` and stays that way unless something explicitly trips
14	//! it.
15	//!
16	//! The tests use `Environment::set_interrupt` to install a shared
17	//! `Interrupt` and `Interrupt::set()` (called from a background
18	//! thread or pre-eval) to simulate the server-side `/cancel` flip.
19	
20	use std::sync::Arc;
21	use std::sync::atomic::{AtomicUsize, Ordering};
22	use std::thread;
23	use std::time::Duration;
24	
25	use mlpl_eval::{Environment, EvalError, Interrupt, MetricSink, eval_program_value};
26	use mlpl_parser::{lex, parse};
27	
28	fn run(program: &str, env: &mut Environment) -> Result<mlpl_eval::Value, EvalError> {
29	    let tokens = lex(program).expect("lex");
30	    let stmts = parse(&tokens).expect("parse");
31	    eval_program_value(&stmts, env)
32	}
33	
