79	/// Sink that flips the interrupt on the 3rd metric emission so the
80	/// 4th iteration's loop-head check trips. The bubbled `Cancelled`
81	/// carries `step = 3` and the 3 completed losses.
82	#[derive(Debug)]
83	struct CancelAfter {
84	    seen: Arc<AtomicUsize>,
85	    intr: Interrupt,
86	    cutoff: usize,
87	}
88	
89	impl MetricSink for CancelAfter {
90	    fn emit(&self, _name: &str, _step: usize, _value: f64) {
91	        let prev = self.seen.fetch_add(1, Ordering::SeqCst);
92	        if prev + 1 >= self.cutoff {
93	            self.intr.set();
94	        }
95	    }
96	}
