588	fn eval_train(
589	    count: &Expr,
590	    body: &[Expr],
591	    env: &mut Environment,
592	    trace: &mut Option<&mut Trace>,
593	) -> Result<(&'static str, Vec<TraceValue>, DenseArray), EvalError> {
594	    let n_arr = eval_expr(count, env, trace)?.into_array()?;
595	    if n_arr.rank() != 0 {
596	        return Err(EvalError::InvalidRepeatCount);
597	    }
598	    let n = n_arr.data()[0] as usize;
599	    let mut losses: Vec<f64> = Vec::with_capacity(n);
600	    let mut last = DenseArray::from_scalar(0.0);
601	    for i in 0..n {
602	        // Saga 21.5 step 003: cancellation checkpoint at the head
603	        // of every iteration. On trip, persist what we have so the
604	        // session's `last_losses` survives the cancel and return
605	        // an enriched `Cancelled` carrying the current step + the
606	        // partial loss curve.
607	        if env.check_interrupt().is_err() {
608	            return cancel_train(env, i, losses);
609	        }
610	        env.set("step".into(), DenseArray::from_scalar(i as f64));
611	        let mut step_val = DenseArray::from_scalar(0.0);
612	        for stmt in body {
613	            match eval_expr(stmt, env, trace) {
614	                Ok(v) => step_val = v.into_array()?,
615	                Err(EvalError::Cancelled { .. }) => {
616	                    return cancel_train(env, i, losses);
617	                }
618	                Err(e) => return Err(e),
619	            }
620	        }
621	        // Capture the body's final value as the per-step loss; if it
622	        // is non-scalar (e.g. a vector), reduce by mean for the loss
623	        // curve so callers can still rely on a scalar history.
624	        let scalar_loss = if step_val.rank() == 0 {
625	            step_val.data()[0]
626	        } else {
627	            let s: f64 = step_val.data().iter().sum();
628	            s / (step_val.data().len().max(1) as f64)
629	        };
630	        losses.push(scalar_loss);
631	        last = step_val;
632	        // Saga 21.5 step 001: emit live `_metric`-suffixed scalars
633	        // after each iteration so an SSE client can stream loss
634	        // curves while training. Clone the Arc out first to release
635	        // the env borrow before the metric collection loop reborrows.
636	        if let Some(sink) = env.metric_sink() {
637	            let metrics: Vec<(String, f64)> = env
638	                .vars_iter()
639	                .filter(|(name, arr)| name.ends_with("_metric") && arr.rank() == 0)
640	                .map(|(name, arr)| (name.clone(), arr.data()[0]))
641	                .collect();
642	            for (name, value) in metrics {
643	                sink.emit(&name, i, value);
644	            }
645	        }
646	    }
647	    let losses_arr = DenseArray::new(mlpl_array::Shape::new(vec![losses.len()]), losses)
648	        .expect("losses shape matches data");
649	    env.set("last_losses".into(), losses_arr);
650	    Ok(("train", vec![], last))
651	}
