653	/// Saga 21.5 step 003: enrich a bubbled `Cancelled` (from a
654	/// pre-builtin checkpoint deep inside the body, or the loop-head
655	/// check itself) with this `train`'s current iteration index and
656	/// accumulated loss curve, and persist `last_losses` so post-cancel
657	/// `:vars` still sees the partial vector. Returns the enriched
658	/// error wrapped to match `eval_train`'s `Result` signature.
659	fn cancel_train(
660	    env: &mut Environment,
661	    step: usize,
662	    losses: Vec<f64>,
663	) -> Result<(&'static str, Vec<TraceValue>, DenseArray), EvalError> {
664	    let losses_arr = DenseArray::new(mlpl_array::Shape::new(vec![losses.len()]), losses.clone())
665	        .expect("losses shape matches data");
666	    env.set("last_losses".into(), losses_arr);
667	    Err(EvalError::Cancelled {
668	        step,
669	        partial_losses: losses,
670	    })
671	}
