) -> Result<(&'static str, Vec<TraceValue>, DenseArray), EvalError> {
    let n_arr = eval_expr(count, env, trace)?.into_array()?;
    if n_arr.rank() != 0 {
        return Err(EvalError::InvalidRepeatCount);
    }
    let n = n_arr.data()[0] as usize;
    let mut losses: Vec<f64> = Vec::with_capacity(n);
    let mut last = DenseArray::from_scalar(0.0);
    for i in 0..n {
        // Saga 21.5 step 003: cancellation checkpoint at the head
        // of every iteration. On trip, persist what we have so the
        // session's `last_losses` survives the cancel and return
        // an enriched `Cancelled` carrying the current step + the
        // partial loss curve.
        if env.check_interrupt().is_err() {
            return cancel_train(env, i, losses);
        }
        env.set("step".into(), DenseArray::from_scalar(i as f64));
        let mut step_val = DenseArray::from_scalar(0.0);
        for stmt in body {
            match eval_expr(stmt, env, trace) {
                Ok(v) => step_val = v.into_array()?,
                Err(EvalError::Cancelled { .. }) => {
                    return cancel_train(env, i, losses);
                }
                Err(e) => return Err(e),
            }
        }
        // Capture the body's final value as the per-step loss; if it
        // is non-scalar (e.g. a vector), reduce by mean for the loss
        // curve so callers can still rely on a scalar history.
        let scalar_loss = if step_val.rank() == 0 {
            step_val.data()[0]
        } else {
            let s: f64 = step_val.data().iter().sum();
            s / (step_val.data().len().max(1) as f64)
        };
        losses.push(scalar_loss);
        last = step_val;
        // Saga 21.5 step 001: emit live `_metric`-suffixed scalars
        // after each iteration so an SSE client can stream loss
        // curves while training. Clone the Arc out first to release
        // the env borrow before the metric collection loop reborrows.
        if let Some(sink) = env.metric_sink() {
            let metrics: Vec<(String, f64)> = env
                .vars_iter()
                .filter(|(name, arr)| name.ends_with("_metric") && arr.rank() == 0)
                .map(|(name, arr)| (name.clone(), arr.data()[0]))
                .collect();
            for (name, value) in metrics {
                sink.emit(&name, i, value);
            }
        }
    }
    let losses_arr = DenseArray::new(mlpl_array::Shape::new(vec![losses.len()]), losses)
        .expect("losses shape matches data");
    env.set("last_losses".into(), losses_arr);
    Ok(("train", vec![], last))
}

/// Saga 21.5 step 003: enrich a bubbled `Cancelled` (from a
/// pre-builtin checkpoint deep inside the body, or the loop-head
/// check itself) with this `train`'s current iteration index and
/// accumulated loss curve, and persist `last_losses` so post-cancel
/// `:vars` still sees the partial vector. Returns the enriched
/// error wrapped to match `eval_train`'s `Result` signature.
fn cancel_train(
    env: &mut Environment,
    step: usize,
    losses: Vec<f64>,
) -> Result<(&'static str, Vec<TraceValue>, DenseArray), EvalError> {
    let losses_arr = DenseArray::new(mlpl_array::Shape::new(vec![losses.len()]), losses.clone())
        .expect("losses shape matches data");
    env.set("last_losses".into(), losses_arr);
    Err(EvalError::Cancelled {
        step,
        partial_losses: losses,
    })
}

