fn env_is_truthy(v: Option<&str>) -> bool {
    match v {
        None => false,
        Some(s) => {
            let lower = s.trim().to_ascii_lowercase();
            !lower.is_empty() && lower != "0" && lower != "false" && lower != "no" && lower != "off"
        }
    }
}

