1	//! Saga 21 step 003: CLI viz cache strategy.
2	//!
3	//! Replaces `mlpl-repl`'s old raw-`<svg>`-XML print
4	//! path with a write-to-disk + print-the-path
5	//! strategy. Both the local CLI and the
6	//! `--connect <url>` client route every
7	//! `Value::Str` through `transform_value` before
8	//! printing; SVG strings end up at
9	//! `$MLPL_CACHE_DIR/<sha256-prefix>.svg` (default
10	//! `dirs::cache_dir().join("mlpl")`), and non-SVG
11	//! strings pass through unchanged.
12	//!
13	//! Server-side `mlpl-serve` does NOT transform --
14	//! it returns raw SVG strings; clients decide where
15	//! to put them. A future saga may add a server-side
16	//! visualization-storage URL endpoint (out of
17	//! scope here).
18	//!
19	//! Other formats (PNG, HTML, JSON) are deferred --
20	//! `is_svg_string` is the only detector today.
21	
22	use std::fs;
23	use std::path::{Path, PathBuf};
24	
25	use sha2::{Digest, Sha256};
26	
27	const CACHE_DIR_ENV_VAR: &str = "MLPL_CACHE_DIR";
28	const CACHE_DIR_NAME: &str = "mlpl";
29	const HASH_PREFIX_LEN: usize = 12;
30	
31	/// True if `s` looks like an SVG document: optional
32	/// XML prolog + leading `<svg`. Whitespace before
33	/// either token is allowed; we strip it before the
34	/// check.
35	#[must_use]
36	pub fn is_svg_string(s: &str) -> bool {
37	    let trimmed = s.trim_start();
38	    if trimmed.starts_with("<svg") {
39	        return true;
40	    }
41	    if let Some(rest) = trimmed.strip_prefix("<?xml") {
42	        return rest.trim_start().contains("<svg");
43	    }
44	    false
45	}
46	
47	/// Content-addressed cache path for `content` under
48	/// `cache_dir`. The filename is the first
49	/// `HASH_PREFIX_LEN` (12) hex chars of the SHA-256
50	/// of the bytes plus an `.svg` suffix. Deterministic
51	/// (same input -> same path) and content-addressed
52	/// (different input -> different path).
53	#[must_use]
54	pub fn cache_path_for_content(content: &str, cache_dir: &Path) -> PathBuf {
55	    let mut hasher = Sha256::new();
56	    hasher.update(content.as_bytes());
57	    let hex = format!("{:x}", hasher.finalize());
58	    let prefix: String = hex.chars().take(HASH_PREFIX_LEN).collect();
59	    cache_dir.join(format!("{prefix}.svg"))
60	}
61	
62	/// Resolve the cache directory + write `content`
63	/// there, creating the directory if missing. Returns
64	/// the path on success. The caller is expected to
65	/// call this only when `is_svg_string(content)` is
66	/// true.
67	///
68	/// # Errors
69	/// Bubbles up `io::Error` from `create_dir_all` or
70	/// `write` -- caller should fall back to printing
71	/// the raw content if the write fails.
72	pub fn write_to_cache(content: &str, cache_dir: &Path) -> std::io::Result<PathBuf> {
73	    fs::create_dir_all(cache_dir)?;
74	    let path = cache_path_for_content(content, cache_dir);
75	    fs::write(&path, content)?;
76	    Ok(path)
77	}
78	
79	/// Run `s` through the cache transform: SVG strings
80	/// land on disk and come back as `viz: <path>`,
81	/// non-SVG strings pass through unchanged.
82	///
83	/// `cache_dir_override` lets a caller force a
84	/// specific directory (e.g., `--svg-out <dir>` on
85	/// the legacy CLI flag). When `None`, resolves via
86	/// `$MLPL_CACHE_DIR` -> `dirs::cache_dir()/mlpl/`
87	/// -> a tmp-dir fallback (so `transform_value`
88	/// never panics in environments without a valid
89	/// cache dir, e.g. some CI sandboxes).
90	///
