    session.env.clear_peer_dispatcher();
    session.env.clear_interrupt();
    let value = value.map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("{e}"))))?;
    let kind = value_kind(&value);
    Ok(Json(EvalResponse {
        value: format!("{value}"),
        kind,
    }))
