    state: &AppState,
    id: &Uuid,
    session: &mut crate::sessions::Session,
) {
    if let Some(entry) = state.interrupts.read().await.get(id).cloned() {
        entry.interrupt.reset();
        session.env.set_interrupt(entry.interrupt);
    }
}

