/// Saga 21.5 step 004: detect an SVG-returning eval and stash
/// the bytes in `viz_storage` (and the server-side
/// `MLPL_CACHE_DIR` if set). Returns the `(viz_url,
/// viz_local_path)` pair to thread into the eval response.
/// No-op (returns `(None, None)`) for non-string / non-SVG
/// values. Shared by `eval_handler` and the SSE
/// `spawn_eval_task` so both transports surface viz the same
/// way.
pub(crate) async fn attach_viz(
    state: &AppState,
    value: &str,
    kind: &'static str,
) -> (Option<String>, Option<String>) {
    if kind != "string" || !mlpl_cli::viz_cache::is_svg_string(value) {
        return (None, None);
    }
    let (_id, url) =
        crate::viz_storage::put(&state.viz, value.as_bytes().to_vec(), "image/svg+xml".into())
            .await;
    let local = crate::viz_storage::write_to_local_cache(value.as_bytes());
    (Some(url), local)
}

