50	    /// The stream ends with exactly one terminal frame, either
51	    /// `Done` (success) or `Error` (any `EvalError`).
52	    #[derive(Debug, Serialize)]
53	    #[serde(tag = "event", content = "data", rename_all = "lowercase")]
54	    pub enum SseEvent {
55	        Ready,
56	        Metric {
57	            name: String,
58	            step: usize,
59	            value: f64,
60	        },
61	        Done {
62	            value: String,
63	            kind: &'static str,
64	            /// Saga 21.5 step 004: when the eval returned an
65	            /// SVG-shaped string, this carries the URL the
