71	            /// path for the same SVG, when configured.
72	            #[serde(skip_serializing_if = "Option::is_none")]
73	            viz_local_path: Option<String>,
74	        },
75	        /// Saga 21.5 step 003: terminal frame for cooperative
76	        /// cancellation. Mirrors `EvalError::Cancelled`'s `step`
77	        /// and `partial_losses` so clients can render the partial
78	        /// loss curve without falling back to a second
79	        /// `:vars`/inspect round-trip.
80	        Cancelled {
81	            step: usize,
82	            partial_losses: Vec<f64>,
83	        },
