90	        /// Convert one `SseEvent` to an axum `Event` carrying the
91	        /// `event:` line and a `data:` JSON payload. For variants
92	        /// without a body (`Ready`), `data:` is an empty JSON
93	        /// object so clients that always parse `data` do not need
94	        /// a special case.
95	        pub fn to_axum_event(&self) -> Event {
96	            let (name, data) = match self {
97	                Self::Ready => ("ready".to_string(), serde_json::json!({})),
98	                Self::Metric { name, step, value } => (
99	                    "metric".to_string(),
100	                    serde_json::json!({"name": name, "step": step, "value": value}),
101	                ),
102	                Self::Done {
103	                    value,
104	                    kind,
105	                    viz_url,
106	                    viz_local_path,
107	                } => {
108	                    let mut payload = serde_json::json!({"value": value, "kind": kind});
109	                    if let Some(u) = viz_url {
110	                        payload["viz_url"] = serde_json::Value::String(u.clone());
111	                    }
112	                    if let Some(p) = viz_local_path {
113	                        payload["viz_local_path"] = serde_json::Value::String(p.clone());
114	                    }
115	                    ("done".to_string(), payload)
116	                }
117	                Self::Cancelled {
118	                    step,
119	                    partial_losses,
120	                } => (
121	                    "cancelled".to_string(),
122	                    serde_json::json!({"step": step, "partial_losses": partial_losses}),
123	                ),
124	                Self::Error { error } => ("error".to_string(), serde_json::json!({"error": error})),
