/// so the crate module count stays at the sw-checklist budget.
///
/// `POST /v1/viz` accepts a base64 payload + content_type and
/// returns `/v1/viz/<sha256-hex-prefix>`. `GET /v1/viz/:id`
/// serves the bytes back with the recorded content type. The
/// eval pipeline (`eval_handler` and the SSE `spawn_eval_task`)
/// detect SVG-returning programs and stash the bytes here so the
/// non-streaming and streaming responses both carry a `viz_url`.
pub mod viz_storage {
    use std::collections::HashMap;
    use std::path::Path;
    use std::sync::Arc;

    use axum::body::Body;
    use axum::extract::{Path as AxumPath, State};
    use axum::http::{HeaderMap, HeaderValue, StatusCode, header};
    use axum::response::{Json, Response};
    use base64::Engine;
    use base64::engine::general_purpose::STANDARD as BASE64;
    use serde::{Deserialize, Serialize};
    use sha2::{Digest, Sha256};
    use tokio::sync::RwLock;

    use crate::auth::{AuthMode, check_token, extract_bearer};
    use crate::handlers::{ErrorResponse, json_err};
    use crate::server::AppState;

    /// Hex-prefix length used in the public URL. 16 hex chars
    /// (8 bytes) gives more than enough collision resistance
    /// for the loopback / LAN scope while keeping URLs short.
    pub(crate) const HASH_PREFIX_LEN: usize = 16;

    #[derive(Clone)]
    struct StoredEntry {
        bytes: Vec<u8>,
        content_type: String,
    }

    /// In-memory content-addressed store. Keyed by the hex
    /// prefix of the bytes' SHA-256.
    #[derive(Default)]
    pub struct VizStore {
        entries: RwLock<HashMap<String, StoredEntry>>,
    }

    /// Shared handle to the viz store, embedded in `AppState`.
    pub type SharedVizStore = Arc<VizStore>;

    /// Construct a fresh empty store handle.
    #[must_use]
    pub fn new_store() -> SharedVizStore {
        Arc::new(VizStore::default())
    }

    /// Internal helper: insert `(bytes, content_type)` and
    /// return the public URL `/v1/viz/<hex>`. Used both by the
    /// upload handler and by the eval-pipeline integration in
    /// `handlers::attach_viz`.
    pub(crate) async fn put(
        store: &VizStore,
        bytes: Vec<u8>,
        content_type: String,
    ) -> (String, String) {
        let mut hasher = Sha256::new();
        hasher.update(&bytes);
        let hex: String = format!("{:x}", hasher.finalize())
            .chars()
            .take(HASH_PREFIX_LEN)
            .collect();
        store.entries.write().await.insert(
            hex.clone(),
            StoredEntry {
                bytes,
                content_type,
            },
        );
        let url = format!("/v1/viz/{hex}");
        (hex, url)
    }

    /// Side-effecting helper: also write the same bytes to the
    /// server-side `MLPL_CACHE_DIR` so a co-located client (the
    /// common dev-loopback case) can read the file directly.
    /// Returns the absolute path on success; `None` if no
    /// cache dir is configured or the write fails.
    pub(crate) fn write_to_local_cache(bytes: &[u8]) -> Option<String> {
        let dir = std::env::var("MLPL_CACHE_DIR").ok()?;
        let cache_dir = Path::new(&dir);
        let s = std::str::from_utf8(bytes).ok()?;
        match mlpl_cli::viz_cache::write_to_cache(s, cache_dir) {
            Ok(p) => Some(p.display().to_string()),
            Err(_) => None,
        }
    }

    /// Detect an SVG-returning eval and stash the bytes in
    /// `viz_storage` + the server-side `MLPL_CACHE_DIR` (when
    /// set). Returns `(viz_url, viz_local_path)` to thread into
    /// the eval response (and the SSE `done` payload). No-op
    /// (returns `(None, None)`) for non-string / non-SVG values.
    /// Shared by `handlers::eval_handler` and the SSE
    /// `spawn_eval_task` so both transports surface viz
    /// identically.
    pub async fn attach_viz(
        store: &SharedVizStore,
        value: &str,
        kind: &str,
    ) -> (Option<String>, Option<String>) {
        if kind != "string" || !mlpl_cli::viz_cache::is_svg_string(value) {
            return (None, None);
        }
        let (_id, url) = put(store, value.as_bytes().to_vec(), "image/svg+xml".into()).await;
        let local = write_to_local_cache(value.as_bytes());
        (Some(url), local)
    }

    #[derive(Deserialize)]
    pub struct UploadRequest {
        pub bytes_base64: String,
        pub content_type: String,
    }

    #[derive(Serialize)]
    pub struct UploadResponse {
        pub id: String,
        pub url: String,
    }

    type VizError = (StatusCode, Json<ErrorResponse>);

    fn check_bearer_against_any_session(
        headers: &HeaderMap,
        state: &AppState,
        interrupts: &HashMap<uuid::Uuid, crate::sessions::InterruptEntry>,
    ) -> Result<(), VizError> {
        if state.auth_mode != AuthMode::Required {
            return Ok(());
        }
        let provided = extract_bearer(headers).ok_or((
            StatusCode::UNAUTHORIZED,
            json_err("missing or invalid authorization"),
        ))?;
        if interrupts.values().any(|e| check_token(provided, &e.token)) {
            Ok(())
        } else {
            Err((
                StatusCode::UNAUTHORIZED,
                json_err("missing or invalid authorization"),
            ))
        }
    }

    /// `POST /v1/viz` -- requires bearer when `auth_mode ==
    /// Required`. Accepts `{bytes_base64, content_type}` and
    /// returns `{id, url}`. Idempotent: identical bytes yield
    /// identical ids.
    pub async fn upload_handler(
        State(state): State<AppState>,
        headers: HeaderMap,
        Json(body): Json<UploadRequest>,
    ) -> Result<Json<UploadResponse>, VizError> {
        let interrupts = state.interrupts.read().await;
        check_bearer_against_any_session(&headers, &state, &interrupts)?;
        drop(interrupts);
        let bytes = BASE64.decode(body.bytes_base64.as_bytes()).map_err(|e| {
            (
                StatusCode::BAD_REQUEST,
                json_err(format!("base64 decode: {e}")),
            )
        })?;
        let (id, url) = put(&state.viz, bytes, body.content_type).await;
        Ok(Json(UploadResponse { id, url }))
    }

    /// `GET /v1/viz/:id` -- requires bearer when `auth_mode ==
    /// Required`. Returns the stored bytes with the recorded
    /// `Content-Type`. 404 on unknown id.
    pub async fn get_handler(
        State(state): State<AppState>,
        AxumPath(id): AxumPath<String>,
        headers: HeaderMap,
    ) -> Result<Response, VizError> {
        let interrupts = state.interrupts.read().await;
        check_bearer_against_any_session(&headers, &state, &interrupts)?;
        drop(interrupts);
        let entry = state
            .viz
            .entries
            .read()
            .await
            .get(&id)
            .cloned()
            .ok_or((StatusCode::NOT_FOUND, json_err("unknown viz id")))?;
        let mut resp = Response::new(Body::from(entry.bytes));
        if let Ok(value) = HeaderValue::from_str(&entry.content_type) {
            resp.headers_mut().insert(header::CONTENT_TYPE, value);
        }
        Ok(resp)
    }
}

