    let resp: JsonValue = reqwest::Client::new()
        .post(format!("http://{addr}/v1/sessions/{id}/eval"))
        .bearer_auth(&token)
        .json(&serde_json::json!({"program": program}))
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
