    );

    let get = reqwest::Client::new()
        .get(format!("http://{addr}{viz_url}"))
        .bearer_auth(&token)
        .send()
        .await
        .unwrap();
    assert_eq!(get.status(), 200);
    let bytes = get.bytes().await.unwrap();
    assert_eq!(bytes.as_ref(), svg_value.as_bytes());
}

