//! recognizes SVG, HTML, PNG, JPEG (by magic bytes /
//! text-prefix sniffing) plus an explicit
//! `application/json` opt-in. Both the
//! `MLPL_CACHE_DIR` write path and `mlpl-serve`'s
//! `/v1/viz` endpoint use this table so non-SVG viz
//! lands with the right `Content-Type` and the right
//! filename extension.

use std::fs;
use std::path::{Path, PathBuf};

use sha2::{Digest, Sha256};

const CACHE_DIR_ENV_VAR: &str = "MLPL_CACHE_DIR";
const CACHE_DIR_NAME: &str = "mlpl";
const HASH_PREFIX_LEN: usize = 12;

/// Saga 21.5 step 005: kinds of viz payload the cache + storage
/// layer can identify. `detect` returns the first matching
/// variant; the variants below also expose the MIME
/// (`content_type`) and the filename extension (`extension`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VizFormat {
    Svg,
    Html,
    Png,
    Jpeg,
    Json,
}

const PNG_MAGIC: &[u8] = &[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
const JPEG_MAGIC: &[u8] = &[0xFF, 0xD8, 0xFF];
const JSON_OPT_IN: &[u8] = b"#mlpl-viz: json";

impl VizFormat {
    /// Sniff the format from the raw bytes. Returns `None`
    /// when no variant matches; callers fall back to "store
    /// opaquely" (the `/v1/viz` POST handler) or "decline to
    /// cache" (the local `MLPL_CACHE_DIR` path).
    ///
    /// JSON is intentionally opt-in (requires the literal
    /// `#mlpl-viz: json` prefix) because the eval pipeline
    /// often surfaces ordinary string values that happen to
    /// start with `{` -- treating those as viz would write
    /// noise to the cache dir.
    #[must_use]
    pub fn detect(bytes: &[u8]) -> Option<VizFormat> {
        if bytes.starts_with(PNG_MAGIC) {
            return Some(VizFormat::Png);
        }
        if bytes.len() >= 3 && &bytes[..3] == JPEG_MAGIC {
            return Some(VizFormat::Jpeg);
        }
        if bytes.starts_with(JSON_OPT_IN) {
            return Some(VizFormat::Json);
        }
        let text = std::str::from_utf8(bytes).ok()?;
        detect_text(text)
    }

    /// MIME type for `Content-Type` headers on `/v1/viz`
    /// responses.
    #[must_use]
    pub fn content_type(self) -> &'static str {
        match self {
            VizFormat::Svg => "image/svg+xml",
            VizFormat::Html => "text/html",
            VizFormat::Png => "image/png",
            VizFormat::Jpeg => "image/jpeg",
            VizFormat::Json => "application/json",
        }
    }

    /// Filename extension (no leading dot) for cache-dir
    /// writes. `Jpeg` writes as `.jpg` (more conventional
    /// than `.jpeg`).
    #[must_use]
    pub fn extension(self) -> &'static str {
        match self {
            VizFormat::Svg => "svg",
            VizFormat::Html => "html",
            VizFormat::Png => "png",
            VizFormat::Jpeg => "jpg",
            VizFormat::Json => "json",
        }
    }
}

/// Text-prefix sniffing for SVG / HTML. Both formats can be
/// preceded by an XML / HTML prolog and arbitrary whitespace, so
/// we strip leading whitespace before the prefix checks. SVG
/// also accepts `<?xml ...?><svg>` (an XML prolog followed by
/// an `<svg` open).
fn detect_text(s: &str) -> Option<VizFormat> {
    let trimmed = s.trim_start();
    if let Some(rest) = trimmed.strip_prefix("<?xml")
        && rest.trim_start().contains("<svg")
    {
        return Some(VizFormat::Svg);
    }
    if trimmed.starts_with("<svg") {
        return Some(VizFormat::Svg);
    }
    let lower_prefix: String = trimmed
        .chars()
        .take(15)
        .flat_map(char::to_lowercase)
        .collect();
    if lower_prefix.starts_with("<!doctype html") || lower_prefix.starts_with("<html") {
        return Some(VizFormat::Html);
    }
    None
}

