/// XML prolog + leading `<svg`. Wrapper over
/// `VizFormat::detect` for back-compat with the
/// Saga 21 step 003 callers.
#[must_use]
pub fn is_svg_string(s: &str) -> bool {
    VizFormat::detect(s.as_bytes()) == Some(VizFormat::Svg)
}

